// Durations are game minutes (one second at the default speed).
import {BEACH} from './beach-layout.js';
export const WATER_PHASES=[['launch','Mise à l’eau',3],['outbound','Bateau vers la victime',4],['rescue','Plongeurs au contact',6],['inbound','Retour avec la victime',4],['landing','Débarquement sur la berge',2]];
export const WATER_DOCK=BEACH.dock,WATER_VICTIM=[72,-158],WATER_HANDOVER=BEACH.handover;
export function initWaterRescue(c){if(!c.waterRescue)return;const nearBeach=c.setting==='beach-water';c.target=(nearBeach?BEACH.swimmingVictim:WATER_VICTIM).slice();c.accessTarget=BEACH.access.slice();c.actionPoint=WATER_HANDOVER.slice();c.address=nearBeach?BEACH.name+' · zone de baignade':'Étang · accès nautique de la plage';c.site={kind:'water',height:0,position:c.target.slice()};c.patients.forEach(p=>p.trapped=true);c.nautical={phase:0,progress:0,unitId:null,done:false,dock:WATER_DOCK.slice(),victim:c.target.slice(),handover:WATER_HANDOVER.slice()};c.finishBudget+=25;}
export function waterStatus(c){const r=c.nautical;return !r?'':r.done?'Victime sur la berge · prise en charge VSAV':r.unitId?WATER_PHASES[r.phase][1]:'Plongeurs + bateau et VSAV nécessaires';}
export function tickWaterRescue(c,e,minutes,emit){const r=c.nautical;if(!r||r.done||!c.reconComplete||e.status!=='scene')return;if(!r.unitId){r.unitId=e.id;emit('Mise à l’eau du bateau, plongeurs engagés.');}if(r.unitId!==e.id)return;r.progress+=minutes/WATER_PHASES[r.phase][2];if(r.progress<1)return;r.progress=0;r.phase++;if(r.phase>=WATER_PHASES.length){r.done=true;r.phase=WATER_PHASES.length-1;c.patients.forEach(p=>p.trapped=false);emit('Victime ramenée sur la berge. Prise en charge par le VSAV.');}else emit(WATER_PHASES[r.phase][1]+'.');}
export function waterBusy(c,e){return c?.nautical?.unitId===e.id&&!c.nautical.done;}
